	[ANIO] ASC,
	[EVENTO] ASC,
	[CODIGO_DEPARTAMENTO] ASC,
	[CODIGO_PESO_PROMEDIO] ASC,
	[CODIGO_CAUSA] ASC,
	[SEXO] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, SORT_IN_TEMPDB = OFF, IGNORE_DUP_KEY = OFF, ONLINE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [FG_EVENTO_CAUSA_MUERTE] FOREIGN KEY([CODIGO_CAUSA])
REFERENCES [dbo].[CAUSA_MUERTE] ([CODIGO_CAUSA])
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [FG_EVENTO_CAUSA_MUERTE]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [FG_EVENTO_DEPARTAMENTO] FOREIGN KEY([CODIGO_DEPARTAMENTO])
REFERENCES [dbo].[DEPARTAMENTO] ([CODIGO_DEPARTAMENTO])
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [FG_EVENTO_DEPARTAMENTO]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [FG_EVENTO_PESO_PROMEDIO] FOREIGN KEY([CODIGO_PESO_PROMEDIO])
REFERENCES [dbo].[PESO_PROMEDIO] ([CODIGO_PESO_PROMEDIO])
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [FG_EVENTO_PESO_PROMEDIO]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [CK_ANIO] CHECK  (([ANIO]>=(2000) AND [ANIO]<=(2100)))
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [CK_ANIO]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [CK_CANTIDAD] CHECK  (([CANTIDAD]>=(0)))
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [CK_CANTIDAD]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [CK_EVENTO] CHECK  ((([EVENTO]='D' OR [EVENTO]='N') AND ([EVENTO]='N' AND [CODIGO_PESO_PROMEDIO] IS NOT NULL AND [CODIGO_CAUSA] IS NULL OR [EVENTO]='D' AND [CODIGO_PESO_PROMEDIO] IS NULL AND [CODIGO_CAUSA] IS NOT NULL)))
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [CK_EVENTO]
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO]  WITH CHECK ADD  CONSTRAINT [CK_SEXO] CHECK  (([SEXO]='F' OR [SEXO]='M'))
GO
ALTER TABLE [dbo].[REGISTRO_EVENTO] CHECK CONSTRAINT [CK_SEXO]
GO
